// Original, synthetic incident packets. Code samples render as text, never execute here.
export function createIncidentViews({data,esc,link,codeBlock}){
 const cases=data.incidents||[];
 const list=items=>`<ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`;
 const lesson=id=>data.lessons.find(item=>item.id===id);
 const labs=item=>(item.labIds||[]).map(id=>data.labs.find(lab=>lab.id===id)).filter(Boolean);
 const number=item=>item.id.replace('incident-','');
 const card=item=>link(`incident/${item.id}`,`<div class="incident-card-top"><span>CASE ${number(item)}</span><span>STAGE 0${item.stage} ↗</span></div><h3>${esc(item.title)}</h3><p>${esc(item.subtitle)}</p><div class="incident-card-meta"><span>After lesson ${esc(item.afterLesson.replace('lesson-',''))} · ~${item.minutes} min</span><span>${labs(item).length?'Repair lab included':'Project investigation'}</span></div>`,'incident-card');
 function related(items,title='Take it into the incident workshop'){
  if(!items.length)return '';
  return `<section class="incident-related"><span class="eyebrow">WHEN THE HAPPY PATH BREAKS</span><h2>${esc(title)}</h2><p>Supplied evidence, broken code, and a regression to prove your repair.</p><div class="incident-related-links">${items.map(item=>link(`incident/${item.id}`,`<strong>${esc(item.title)}</strong><span>After lesson ${esc(item.afterLesson.replace('lesson-',''))} · ${item.minutes} min ↗</span>`)).join('')}</div></section>`;
 }
 function index(stage=0){
  const shown=cases.filter(item=>!stage||item.stage===stage);
  return `<section class="incident-hero"><div><span class="eyebrow">THE INCIDENT WORKSHOP</span><h1>It worked.<br>Until it didn’t.</h1><p>Practise the part between a vague bug report and a fix you can trust. Follow the evidence, challenge your first explanation, and protect the repair with a regression test.</p><div class="incident-hero-meta"><span>${cases.length} original case files</span><span>${data.labs.filter(l=>l.kind==='incident').length} executable repair labs</span><span>6 stages</span></div></div><div class="incident-method"><span class="tiny-label">YOUR INVESTIGATION LOOP</span>${[['01','Reproduce','Make the failure happen on demand.'],['02','Explain','Separate observations from assumptions.'],['03','Repair','Change the smallest responsible boundary.'],['04','Prove','Fail before the fix. Pass after it.']].map(([n,title,body])=>`<div><b>${n}</b><section><h3>${title}</h3><p>${body}</p></section></div>`).join('')}</div></section>
  <div class="incident-intro"><p>These are fictional practice incidents with synthetic data. Start after the listed lesson. Some run in the lab; others need your local browser or Node project. A passing lab is one piece of evidence, not proof that the whole incident is solved.</p><div><a class="button outline small" href="incident-workbook.md" download>Download workbook ↓</a><a class="button dark small" href="incident-kits.zip" download>Download case files ↓</a></div></div>
  <div class="filter-tabs" aria-label="Filter incidents by stage">${[0,...data.stages.map(s=>s.id)].map(id=>`<button data-stage="${id}" class="${stage===id?'selected':''}" aria-pressed="${stage===id}">${id?'Stage 0'+id:'All stages'}</button>`).join('')}</div>
  <div class="incident-grid">${shown.map(card).join('')}</div>
  <section class="incident-standard"><span class="eyebrow">THE EVIDENCE STANDARD</span><h2>A fix is more than a green check.</h2><p>Keep the failing input and a repeatable sequence. Record the first wrong assumption, the root cause, the regression test, and what your fix still cannot guarantee. Then carry one failure rehearsal into the stage project.</p><a class="text-link" href="curriculum-review.md" download>Read the curriculum audit and remaining gaps ↓</a></section>`;
 }
 function detail(id,notes={}){
  const item=cases.find(item=>item.id===id);
  if(!item)return null;
  const prerequisites=(item.lessonIds||[item.afterLesson]).map(lesson).filter(Boolean);
  return `<a class="back-link" href="#/incidents">← All incident cases</a><div class="incident-heading"><span class="eyebrow">CASE ${number(item)} / STAGE 0${item.stage} · SYNTHETIC INCIDENT</span><h1>${esc(item.title)}</h1><p>${esc(item.subtitle)}</p><div class="inline-meta"><span>~${item.minutes} minutes</span><span>After lesson ${esc(item.afterLesson.replace('lesson-',''))}</span></div></div>
  <div class="incident-layout"><article class="incident-article">
   <section class="incident-report"><span class="eyebrow">THE REPORT</span><p>${esc(item.report)}</p></section>
   <section><h2>What you have to work with</h2><p class="incident-environment">${esc(item.environment)}</p>${item.evidence.map(e=>`<div class="incident-evidence"><h3>${esc(e.label)}</h3><pre>${esc(e.text)}</pre></div>`).join('')}</section>
   <section><h2>Reproduce before changing anything</h2><ol class="incident-steps">${item.reproduce.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></section>
   <section><h2>The code you inherited</h2><p>Deliberately flawed. Treat its current behavior as evidence, not the specification.</p>${codeBlock(item.starter)}${item.files.map(file=>`<details class="incident-file"><summary>Fixture · ${esc(file.name)}</summary><pre><code>${esc(file.content)}</code></pre></details>`).join('')}</section>
   <section><h2>Keep these constraints</h2>${list(item.constraints)}</section>
   <section class="incident-acceptance"><span class="eyebrow">PROVE THE REPAIR</span><h2>You’re done when you can show this</h2>${list(item.acceptance)}</section>
   ${labs(item).length?`<section class="incident-labs"><h2>Repair the focused boundary</h2><p>The executable lab isolates one mechanism. Return here afterward to finish the wider investigation.</p>${labs(item).map(lab=>link(`lab/${lab.id}`,`${esc(lab.title)} · ${lab.tests.length} checks ↗`,'button dark')).join('')}</section>`:''}
   <section class="incident-help"><h2>Stuck? Take one clue at a time.</h2>${item.hints.map((hint,i)=>`<details><summary>Clue ${i+1}</summary><p>${esc(hint)}</p></details>`).join('')}<details class="incident-debrief"><summary>Open the debrief after your attempt</summary>${list(item.debrief)}</details></section>
   <section class="incident-variation"><span class="eyebrow">CHANGE THE CONDITIONS</span><h2>One more thing breaks</h2><p>${esc(item.variation)}</p></section>
   <section class="lesson-note incident-note"><label for="incident-note">Your investigation record</label><p>Write what you observed, what you ruled out, and why the repair holds. Included in My notebook backups.</p><textarea id="incident-note" data-note="${esc(item.id)}" maxlength="30000" placeholder="Reproduction:\nEvidence and hypotheses:\nRoot cause:\nFix and failing-before / passing-after test:\nRecovery and remaining limitations:">${esc(notes[item.id]||'')}</textarea><small data-note-status role="status">Saved automatically on this device.</small></section>
  </article><aside class="incident-rail"><div class="incident-case-file"><span class="eyebrow">CASE FILE / ${number(item)}</span><h3>Keep the evidence.</h3><p>Download the starter, fixtures, and brief to work in your own environment.</p><button class="button outline small" data-action="download-incident" data-id="${esc(item.id)}">Download this packet ↓</button><small>Public synthetic material only. Your investigation notes stay in your private backup.</small></div><h3>Prepare, then investigate</h3>${prerequisites.map(l=>link(`lesson/${l.id}`,`${String(l.number).padStart(2,'0')} · ${esc(l.title)}`)).join('')}<h3>Apply it to your project</h3>${link(`project/${item.projectId}`,esc(data.projects.find(p=>p.id===item.projectId)?.title||'Stage project'))}<h3>Check the platform contract</h3>${item.resources.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a>`).join('')}<small>Use documentation to verify a hypothesis. A reference is not a substitute for a reproduction.</small></aside></div>`;
 }
 return {index,detail,lessonLinks:id=>related(cases.filter(item=>item.lessonIds.includes(id))),projectLinks:id=>related(cases.filter(item=>item.projectId===id),'Rehearse failure before you call it finished')};
}
